CREATE OR REPLACE FUNCTION public.update_bank_transfer_group_profile(p_collection_id uuid, p_group_name text, p_group_description text, p_group_image_url text DEFAULT NULL::text, p_group_accent_color_hex text DEFAULT NULL::text, p_group_is_public boolean DEFAULT false, p_group_recurring_cadence text DEFAULT 'monthly'::text, p_group_collection_type text DEFAULT NULL::text, p_group_category_subtype text DEFAULT NULL::text, p_group_purpose_label text DEFAULT NULL::text, p_group_is_recurring boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  preserve_platform_public boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not exists (
    select 1 from public.collections collection
    where collection.id = p_collection_id
      and collection.creator_user_id = auth.uid()
      and collection.archived_at is null
  ) then raise exception 'Only the current group owner can update group settings'; end if;
  select collection.public_status = 'public_approved'
  into preserve_platform_public
  from public.collections collection
  where collection.id = p_collection_id;
  perform public.update_collection_profile(
    p_collection_id, p_group_name, p_group_description,
    p_group_image_url, p_group_accent_color_hex,
    preserve_platform_public, p_group_recurring_cadence, p_group_collection_type,
    p_group_category_subtype, p_group_purpose_label, p_group_is_recurring
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_collection_profile(collection uuid, group_name text, group_description text, group_image_url text DEFAULT NULL::text, group_accent_color_hex text DEFAULT NULL::text, group_is_public boolean DEFAULT false, group_recurring_cadence text DEFAULT 'monthly'::text, group_collection_type text DEFAULT NULL::text, group_category_subtype text DEFAULT NULL::text, group_purpose_label text DEFAULT NULL::text, group_is_recurring boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  clean_name text := trim(coalesce(group_name, ''));
  clean_description text := trim(coalesce(group_description, ''));
  clean_cadence text := coalesce(nullif(trim(group_recurring_cadence), ''), 'monthly');
  clean_type text;
  clean_subtype text;
  clean_purpose_label text;
  catalog_choice jsonb;
  current_row public.collections;
  next_public_status public.collection_visibility;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not public.user_is_collection_admin(collection, auth.uid()) then
    raise exception 'Only collection admins can update the group profile';
  end if;
  if char_length(clean_name) not between 3 and 120 then
    raise exception 'Group name must be between 3 and 120 characters';
  end if;
  if char_length(clean_description) > 1000 then
    raise exception 'Group description must be 1000 characters or fewer';
  end if;
  if clean_cadence not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unsupported recurring cadence';
  end if;

  select c.* into current_row from public.collections c where c.id = collection;
  if current_row.id is null then raise exception 'Group not found'; end if;
  if current_row.archived_at is not null then raise exception 'Archived groups cannot be updated'; end if;

  next_public_status := case
    when not coalesce(group_is_public, false) then 'private'::public.collection_visibility
    when current_row.public_status = 'public_approved' then 'public_approved'::public.collection_visibility
    else 'public_requested'::public.collection_visibility
  end;

  catalog_choice := public.resolve_collection_catalog_choice(
    coalesce(nullif(trim(group_collection_type), ''), current_row.collection_type),
    coalesce(nullif(trim(group_category_subtype), ''), current_row.category_subtype),
    coalesce(nullif(trim(group_purpose_label), ''), current_row.purpose_label),
    'RW'
  );
  clean_type := catalog_choice->>'collection_type';
  clean_subtype := catalog_choice->>'category_subtype';
  clean_purpose_label := catalog_choice->>'purpose_label';

  update public.collections
  set title = clean_name,
      description = clean_description,
      cover_image_url = nullif(trim(group_image_url), ''),
      accent_color_hex = nullif(trim(group_accent_color_hex), ''),
      public_status = next_public_status,
      visibility = case
        when next_public_status = 'public_approved' then 'public_approved'::public.collection_visibility
        else 'private'::public.collection_visibility
      end,
      is_recurring = coalesce(group_is_recurring, false),
      recurring_cadence = clean_cadence,
      recurring_rule = case
        when coalesce(group_is_recurring, false)
          then jsonb_build_object('cadence', clean_cadence)
        else null
      end,
      collection_type = clean_type,
      category_subtype = clean_subtype,
      purpose_label = clean_purpose_label,
      updated_at = now()
  where id = collection;

  perform public.create_audit_log(
    'collection.profile_updated',
    'collection',
    collection,
    jsonb_build_object(
      'public_status', next_public_status::text,
      'is_recurring', coalesce(group_is_recurring, false),
      'recurring_cadence', clean_cadence,
      'collection_type', clean_type,
      'category_subtype', clean_subtype,
      'purpose_label', clean_purpose_label
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_collection_receiver(collection uuid, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text DEFAULT 'Primary MOMO receiver'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  collection_row public.collections;
  clean_label text := coalesce(
    nullif(trim(receiver_label), ''),
    'Primary MOMO receiver'
  );
  submitted_digits text := regexp_replace(
    coalesce(receiver_momo_number, ''),
    '[^0-9]',
    '',
    'g'
  );
  profile_digits text;
  canonical_receiver text;
  computed_receiver_hash text;
  previous_receiver_hash text;
  previous_receiver_user_id uuid;
  receiver_is_code boolean;
  member_user_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select collection_row_value.*
  into collection_row
  from public.collections collection_row_value
  where collection_row_value.id = collection
  for update;

  if collection_row.id is null or collection_row.creator_user_id <> auth.uid() then
    raise exception 'Only the group owner can update the receiver';
  end if;

  receiver_is_code := lower(clean_label) like '%code%';
  if receiver_is_code then
    select regexp_replace(coalesce(profile.momo_pay_code, ''), '[^0-9]', '', 'g')
    into profile_digits
    from public.profiles profile
    where profile.id = auth.uid();
    if profile_digits !~ '^[0-9]{4,9}$' then
      raise exception 'Link a valid MoMo code to your profile first';
    end if;
    canonical_receiver := '+' || profile_digits;
  else
    select regexp_replace(coalesce(profile.momo_number, ''), '[^0-9]', '', 'g')
    into profile_digits
    from public.profiles profile
    where profile.id = auth.uid();
    if profile_digits ~ '^250[0-9]{9}$' then
      canonical_receiver := '+' || profile_digits;
    elsif profile_digits ~ '^0[0-9]{9}$' then
      canonical_receiver := '+250' || substr(profile_digits, 2);
    else
      raise exception 'Link a valid Rwanda MoMo number to your profile first';
    end if;
  end if;

  if submitted_digits <> regexp_replace(canonical_receiver, '[^0-9]', '', 'g')
     and not (
       not receiver_is_code
       and submitted_digits ~ '^0[0-9]{9}$'
       and substr(submitted_digits, 2) = substr(
         regexp_replace(canonical_receiver, '[^0-9]', '', 'g'),
         4
       )
     ) then
    raise exception 'Receiver must match the MoMo receiver linked to your profile';
  end if;

  computed_receiver_hash := encode(digest(canonical_receiver, 'sha256'), 'hex');
  if lower(trim(coalesce(receiver_momo_number_hash, ''))) <> computed_receiver_hash then
    raise exception 'Receiver verification failed';
  end if;

  select route.momo_number_hash, route.receiver_user_id
  into previous_receiver_hash, previous_receiver_user_id
  from public.collection_receivers route
  where route.collection_id = collection
    and route.is_active
  order by route.created_at desc
  limit 1;

  -- A profile-only save must not rotate an unchanged financial route or be
  -- blocked by pending intents. Label changes are non-financial metadata.
  if previous_receiver_hash = computed_receiver_hash
     and previous_receiver_user_id = auth.uid() then
    update public.collection_receivers
    set label = clean_label
    where collection_id = collection
      and is_active;
    update public.collections
    set receiver_display_label = clean_label,
        updated_at = now()
    where id = collection;
    return;
  end if;

  update public.payment_intents
  set status = 'expired'
  where collection_id = collection
    and status = 'pending'
    and expires_at <= now();
  if exists (
    select 1
    from public.payment_intents intent
    where intent.collection_id = collection
      and intent.status = 'pending'
  ) then
    raise exception 'Receiver cannot change while contribution requests are pending';
  end if;

  update public.collection_receivers
  set is_active = false
  where collection_id = collection
    and is_active;

  insert into public.collection_receivers (
    collection_id,
    receiver_user_id,
    momo_number,
    momo_number_hash,
    label,
    is_active
  ) values (
    collection,
    auth.uid(),
    canonical_receiver,
    computed_receiver_hash,
    clean_label,
    true
  );

  update public.collections
  set receiver_display_label = clean_label,
      updated_at = now()
  where id = collection;

  insert into public.audit_logs (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    metadata
  ) values (
    auth.uid(),
    'collection.receiver_updated',
    'collection',
    collection,
    jsonb_build_object(
      'receiver_label', clean_label,
      'previous_receiver_hash', previous_receiver_hash,
      'new_receiver_hash', computed_receiver_hash,
      'profile_derived', true,
      'owner_only', true
    )
  );

  for member_user_id in
    select distinct member.user_id
    from public.collection_members member
    where member.collection_id = collection
      and member.status = 'active'
      and member.user_id <> auth.uid()
  loop
    perform public.enqueue_notification_template_event(
      member_user_id,
      'group.update.default',
      jsonb_build_object('group', collection_row.title),
      collection,
      '/groups/' || collection::text,
      'en'
    );
  end loop;
end;
$function$
